//! Pre-apply validation for package-owned PostgreSQL migration artifacts.
//!
//! `docs/architecture/application-naming.md` owns schema selection: migrations
//! author it and therefore require qualified DDL, while SQL corpora inherit the
//! host-selected `search_path` and refuse qualified references. This is the same
//! boundary frozen in `wamn:postgres@0.1.0`, where the host selects the schema
//! and guests name relations unqualified.
//!
//! The validator intentionally admits only the DDL shapes currently demanded by
//! Receiving: schema-qualified ordinary `CREATE TABLE`, one additive client
//! column, or one named client check constraint. PostgreSQL remains responsible
//! for parsing definitions, while post-apply catalog introspection validates
//! their resulting objects. This layer refuses statement operations that the
//! final catalog state cannot prove.

use std::ffi::OsStr;
use std::fmt;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

/// Stable internal class for a refused migration artifact.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum MigrationPolicyErrorKind {
    NotSqlArtifact,
    ArtifactRead,
    EmptyArtifact,
    InvalidSql,
    SetRole,
    RoleOperation,
    GrantOperation,
    NontransactionalOperation,
    CrossSchemaMutation,
    UnnamedConstraint,
    ConstraintNameTooLong,
    RuledOperation,
    UnsupportedStatement,
}

/// Managed PostgreSQL definition addressed by a migration statement.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DefinitionKind {
    Relation,
    Field,
    Constraint,
}

impl DefinitionKind {
    /// Stable catalog spelling for the ownership ledger.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Relation => "relation",
            Self::Field => "field",
            Self::Constraint => "constraint",
        }
    }
}

/// Structural action one migration statement takes on a managed definition.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DefinitionAction {
    Create,
    Add,
    Alter,
    Drop,
}

/// One schema-qualified definition mutation extracted by the migration loader.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DefinitionMutation {
    action: DefinitionAction,
    kind: DefinitionKind,
    schema: Box<str>,
