        transaction,
        booking.idempotency_key.clone(),
        booking.canonical_command.clone(),
        WamnUuid(booking.dock_id.clone()),
    )
    .await
    .map_err(|source| {
        Failure::from_statement("claim the idempotency key", "appointment.book", source)
    })?;
    let Some(claim) = claim else {
        let replay = book_sql::find_replay(transaction, booking.idempotency_key.clone())
            .await
            .map_err(|source| {
                Failure::from_statement(
                    "load the concurrent booking replay",
                    "appointment.book",
                    source,
                )
            })?
            .ok_or_else(|| {
                Failure::internal("a conflicting command claim has no durable result")
            })?;
        return replay_booking(
            transaction,
            &replay.canonical_command,
            replay.appointment_id,
            &booking.canonical_command,
        )
        .await;
    };

    book_sql::load_carrier(transaction, WamnUuid(booking.carrier_id.clone()))
        .await
        .map_err(|source| Failure::from_statement("load the carrier", "appointment.book", source))?
        .ok_or_else(|| {
            Failure::field_id(
                "carrier_not_found",
                "carrier does not exist",
                "carrier_id",
                &booking.carrier_id,
            )
        })?;

    // The dock row is the serialization point for this dock. Every booking on
    // it takes this lock before it reads the neighbours, so two bookings that
    // overlap cannot both pass the probe below.
    book_sql::lock_dock(transaction, WamnUuid(booking.dock_id.clone()))
        .await
        .map_err(|source| Failure::from_statement("lock the dock", "appointment.book", source))?
        .ok_or_else(|| {
            Failure::field_id(
                "dock_not_found",
                "dock does not exist",
                "dock_id",
                &booking.dock_id,
            )
        })?;

    if book_sql::find_overlap(
        transaction,
        WamnUuid(booking.dock_id.clone()),
        TimestampTz(booking.slot_start.clone()),
        TimestampTz(booking.slot_end.clone()),
    )
    .await
    .map_err(|source| {
        Failure::from_statement("probe the dock slot", "appointment.book", source)
    })?
    .is_some()
    {
        return Err(Failure::field(
            "slot_unavailable",
            "the requested slot overlaps an appointment already on that dock",
            "slot_start",
        ));
    }

    let row = book_sql::insert_appointment(
        transaction,
        claim.appointment_id,
        WamnUuid(booking.dock_id.clone()),
        WamnUuid(booking.carrier_id.clone()),
        TimestampTz(booking.slot_start.clone()),
        TimestampTz(booking.slot_end.clone()),
    )
    .await
    .map_err(|source| {
        Failure::from_statement("insert the appointment", "appointment.book", source)
    })?;
    into_appointment_value!(row)
}

/// Book one slot on one dock for one carrier, under an idempotency key.
pub async fn appointment_book(input: &str) -> Result<String, InvocationError> {
    let items = prepare_envelope(input)?;
    let mut connection = Connection::new();
    let mut output: Vec<ItemResult<AppointmentValue>> = Vec::with_capacity(items.len());
    for item in items.into_vec() {
        let result = async {
            let parsed = parse_item::<BookInput>(&item)?;
            let booking = prepare_booking(&parsed)?;
            let mut transaction = begin(&mut connection, "appointment.book").await?;
            let value = book_in(&mut transaction, &booking).await?;
            commit(transaction, "appointment.book").await?;
            Ok::<_, Failure>(value)
        }
        .await;
        output.push(match result {
            Ok(value) => succeeded(item.request_id, value),
            Err(failure) => refused(item.request_id, &failure),
        });
    }
    Ok(serialized(&output))
}

async fn check_in_at(
    transaction: &mut Transaction,
    appointment_id: &str,
    arrived_at: String,
) -> Result<AppointmentValue, Failure> {
    let locked = check_in_sql::lock_appointment(transaction, WamnUuid(appointment_id.to_owned()))
        .await
        .map_err(|source| {
            Failure::from_statement("lock the appointment", "appointment.check_in", source)
        })?
        .ok_or_else(|| {
            Failure::field_id(
                "not_found",
                "appointment does not exist",
                "appointment_id",
                appointment_id,
            )
        })?;
    if locked.status != "scheduled" {
        return Err(Failure::field_id(
            "appointment_not_scheduled",
            "appointment already moved past scheduled",
            "appointment_id",
            appointment_id,
        ));
    }
    let row = check_in_sql::record_arrival(
        transaction,
        WamnUuid(appointment_id.to_owned()),
        TimestampTz(arrived_at),
    )
    .await
    .map_err(|source| {
        Failure::from_statement("record the arrival", "appointment.check_in", source)
    })?;
    into_appointment_value!(row)
}

/// Record an arrival against one booked appointment.
pub async fn appointment_check_in(input: &str) -> Result<String, InvocationError> {
    let items = prepare_envelope(input)?;
    let mut connection = Connection::new();
    let mut output: Vec<ItemResult<AppointmentValue>> = Vec::with_capacity(items.len());
    for item in items.into_vec() {
        let result = async {
            let parsed = parse_item::<CheckInInput>(&item)?;
            let appointment_id = parse_uuid(&parsed.appointment_id, "appointment_id")?;
            let arrived_at = bind_timestamp(parse_timestamp(&parsed.arrived_at, "arrived_at")?);
            let mut transaction = begin(&mut connection, "appointment.check_in").await?;
            let value = check_in_at(&mut transaction, &appointment_id, arrived_at).await?;
            commit(transaction, "appointment.check_in").await?;
            Ok::<_, Failure>(value)
        }
        .await;
        output.push(match result {
            Ok(value) => succeeded(item.request_id, value),
            Err(failure) => refused(item.request_id, &failure),
        });
    }
    Ok(serialized(&output))
}

/// List one dock's appointments for one day, filtered by status, in slot order.
pub async fn appointment_query(input: &str) -> Result<String, InvocationError> {
    let items = prepare_envelope(input)?;
    let mut connection = Connection::new();
    let mut output: Vec<ItemResult<AppointmentsValue>> = Vec::with_capacity(items.len());
    for item in items.into_vec() {
        let result = async {
            let parsed = parse_item::<QueryInput>(&item)?;
            let dock_id = parse_uuid(&parsed.dock_id, "dock_id")?;
            let (day_start, day_end) = parse_day(&parsed.day, "day")?;
            if !STATUS_VALUES.contains(&parsed.status.as_ref()) {
                return Err(Failure::invalid_input(
                    "status is outside the closed vocabulary",
                    "status",
                ));
            }
            let mut transaction = begin(&mut connection, "appointment.query").await?;
            let rows = query_sql::appointment_by_slot_start(
                &mut transaction,
                WamnUuid(dock_id),
                parsed.status.to_string(),
                TimestampTz(bind_timestamp(day_start)),
                TimestampTz(bind_timestamp(day_end)),
            )
            .await
            .map_err(|source| {
                Failure::from_statement("list the dock day", "appointment.query", source)
            })?;
            commit(transaction, "appointment.query").await?;
            let appointments = rows
                .into_iter()
                .map(|row| into_appointment_value!(row))
                .collect::<Result<Vec<_>, Failure>>()?;
            Ok::<_, Failure>(AppointmentsValue {
                appointments: appointments.into_boxed_slice(),
            })
        }
        .await;
        output.push(match result {
            Ok(value) => succeeded(item.request_id, value),
            Err(failure) => refused(item.request_id, &failure),
        });
    }
    Ok(serialized(&output))
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::{
        AppointmentValue, AppointmentsValue, BookInput, EnvelopeItem, ItemResult, OperationError,
        appointment_value, parse_item, prepare_booking, prepare_envelope, refused, serialized,
        succeeded,
    };
    use crate::error::Failure;

    fn book_input(key: &str, start: &str, end: &str) -> BookInput {
        let item = EnvelopeItem {
            request_id: "r-1".into(),
            body: json!({
                "idempotency_key": key,
                "carrier_id": "11111111-1111-4111-8111-111111111111",
                "dock_id": "22222222-2222-4222-8222-222222222222",
                "slot_start": start,
                "slot_end": end,
            }),
        };
        parse_item::<BookInput>(&item).expect("the fixture matches the input contract")
    }

    #[test]
    fn one_booking_has_one_identity_however_its_caller_spells_it() {
        let sent = prepare_booking(&book_input(
            "k-1",
            "2026-10-01T09:00:00Z",
            "2026-10-01T10:00:00Z",
        ))
        .expect("the booking canonicalizes");
        let respelled = prepare_booking(&book_input(
            "k-1",
            "2026-10-01T11:00:00+02:00",
            "2026-10-01T10:00:00.000Z",
        ))
        .expect("the booking canonicalizes");
        assert_eq!(sent.canonical_command, respelled.canonical_command);
    }

    #[test]
    fn a_different_slot_under_one_key_is_a_different_identity() {
        let first = prepare_booking(&book_input(
            "k-1",
            "2026-10-01T09:00:00Z",
            "2026-10-01T10:00:00Z",
        ))
        .expect("the booking canonicalizes");
        let second = prepare_booking(&book_input(
            "k-1",
            "2026-10-01T14:00:00Z",
            "2026-10-01T15:00:00Z",
        ))
        .expect("the booking canonicalizes");
        assert_ne!(first.canonical_command, second.canonical_command);
    }

    #[test]
    fn the_command_identity_is_sorted_compact_canonical_json() {
        let booking = prepare_booking(&book_input(
            "k-1",
            "2026-10-01T09:00:00Z",
            "2026-10-01T10:00:00Z",
        ))
        .expect("the booking canonicalizes");
        assert_eq!(
            String::from_utf8(booking.canonical_command).expect("canonical bytes are UTF-8"),
            concat!(
                r#"{"carrier_id":"11111111-1111-4111-8111-111111111111","#,
                r#""dock_id":"22222222-2222-4222-8222-222222222222","#,
                r#""slot_end":"2026-10-01T10:00:00.000000Z","#,
                r#""slot_start":"2026-10-01T09:00:00.000000Z"}"#,
            )
        );
    }

    #[test]
    fn an_empty_or_backwards_slot_refuses_before_any_statement_runs() {
        let backwards = prepare_booking(&book_input(
            "k-1",
            "2026-10-01T10:00:00Z",
            "2026-10-01T09:00:00Z",
        ))
        .expect_err("a backwards slot refuses");
        assert_eq!(backwards.code(), "invalid_input");
        let empty = prepare_booking(&book_input(
            "k-1",
            "2026-10-01T09:00:00Z",
            "2026-10-01T09:00:00Z",
        ))
        .expect_err("an empty slot refuses");
        assert_eq!(empty.code(), "invalid_input");
        let unkeyed = prepare_booking(&book_input(
            "",
            "2026-10-01T09:00:00Z",
            "2026-10-01T10:00:00Z",
        ))
        .expect_err("an empty key refuses");
        assert_eq!(unkeyed.code(), "invalid_input");
    }

    #[test]
    fn an_envelope_is_one_to_one_hundred_identified_items() {
        let items = prepare_envelope(r#"[{"request_id":"r-1","name":"Door 7"}]"#)
            .expect("one identified item is an envelope");
        assert_eq!(items.len(), 1);
        assert_eq!(items[0].request_id.as_ref(), "r-1");
        assert_eq!(items[0].body, json!({"name": "Door 7"}));
        for rejected in ["[]", "{}", r#"[{"name":"Door 7"}]"#, r#"[{"request_id":""}]"#] {
            assert!(prepare_envelope(rejected).is_err(), "{rejected}");
        }
    }

    #[test]
    fn an_unknown_member_refuses_rather_than_being_ignored() {
        let item = EnvelopeItem {
            request_id: "r-1".into(),
            body: json!({"name": "Door 7", "colour": "red"}),
        };
        assert_eq!(
            parse_item::<super::NameInput>(&item)
                .expect_err("an unknown member refuses")
                .code(),
            "invalid_input"
        );
    }

    #[test]
    fn a_refused_item_carries_its_request_id_and_typed_code() {
        let failure = Failure::field(
            "slot_unavailable",
            "the requested slot overlaps an appointment already on that dock",
            "slot_start",
        );
        let output: Vec<ItemResult<AppointmentValue>> = vec![refused("r-9".into(), &failure)];
        assert_eq!(
            serialized(&output),
            r#"[{"request_id":"r-9","error":{"code":"slot_unavailable","detail":{"field":"slot_start"}}}]"#
        );
    }

    #[test]
    fn a_listed_day_is_one_array_under_one_name() {
        let value = AppointmentsValue {
            appointments: vec![
                appointment_value(
                    "33333333-3333-4333-8333-333333333333",
                    "22222222-2222-4222-8222-222222222222",
                    "11111111-1111-4111-8111-111111111111",
                    "2026-10-01T09:00:00.000000+00:00",
                    "2026-10-01T10:00:00.000000+00:00",
                    "scheduled".to_owned(),
                    None,
                    1,
                )
                .expect("stored timestamps re-spell"),
            ]
            .into_boxed_slice(),
        };
        let output = vec![succeeded("r-1".into(), value)];
        assert_eq!(
            serialized(&output),
            concat!(
                r#"[{"request_id":"r-1","value":{"appointments":[{"#,
                r#""appointment_id":"33333333-3333-4333-8333-333333333333","#,
                r#""dock_id":"22222222-2222-4222-8222-222222222222","#,
                r#""carrier_id":"11111111-1111-4111-8111-111111111111","#,
                r#""slot_start":"2026-10-01T09:00:00Z","#,
                r#""slot_end":"2026-10-01T10:00:00Z","#,
                r#""status":"scheduled","arrived_at":null,"row_version":"1"}]}}]"#,
            )
        );
    }

    #[test]
    fn an_arrival_reports_the_instant_the_caller_supplied() {
        let value = appointment_value(
            "33333333-3333-4333-8333-333333333333",
            "22222222-2222-4222-8222-222222222222",
            "11111111-1111-4111-8111-111111111111",
            "2026-10-01T09:00:00.000000+00:00",
            "2026-10-01T10:00:00.000000+00:00",
            "arrived".to_owned(),
            Some("2026-10-01T09:07:00.000000+00:00"),
            2,
        )
        .expect("stored timestamps re-spell");
        assert_eq!(value.status.as_ref(), "arrived");
        assert_eq!(
            value.arrived_at.as_deref(),
            Some("2026-10-01T09:07:00Z")
        );
        assert_eq!(value.row_version.as_ref(), "2");
    }

    #[test]
    fn every_refusal_shape_the_manifest_declares_serializes_as_declared() {
        for (failure, expected) in [
            (
                Failure::invalid_input("bad", "day"),
                r#"{"code":"invalid_input","detail":{"field":"day"}}"#,
            ),
            (
                Failure::field_id("not_found", "gone", "appointment_id", "abc"),
                r#"{"code":"not_found","detail":{"field":"appointment_id","id":"abc"}}"#,
            ),
            (
                Failure::internal("boom"),
                r#"{"code":"internal_error","detail":{}}"#,
            ),
        ] {
            let error = OperationError {
                code: failure.code(),
                detail: failure.detail().clone(),
            };
            assert_eq!(
                serde_json::to_string(&error).expect("the refusal serializes"),
                expected
            );
        }
    }
}
